class Font;
class PanelQuad;

class PanelFile
{
public:
  PanelQuad *GetPointer(const char *name);
};

class TextBase
{
  char padding[76];
};

class FontTarget
{
public:
  virtual void slot0();
  virtual void slot1();
  virtual void slot2();
  virtual void slot3();
  virtual void slot4();
  virtual void slot5();
  virtual void slot6();
  virtual void slot7();
  virtual void slot8();
  virtual void slot9();
  virtual void slot10();
  virtual void slot11();
  virtual void slot12();
  virtual void setFont(Font *font);
};

class TextString : public TextBase, public FontTarget
{
};

class IGOWidget
{
  char padding[8];
};

class ReplayWidget : public IGOWidget
{
  int vcrButton;
  int vcrButtonHL;
  PanelQuad *vcrPQ;
  PanelQuad *vcrHLPQ;
  PanelQuad *vcrBGPQ;
  PanelQuad *restartPQ;
  PanelQuad *restartOffPQ;
  PanelQuad *restartHLPQ;
  PanelQuad *pausePQ;
  PanelQuad *pauseOffPQ;
  PanelQuad *pauseHLPQ;
  PanelQuad *playPQ;
  PanelQuad *playOffPQ;
  PanelQuad *playHLPQ;
  PanelQuad *slowPQ;
  PanelQuad *slowOffPQ;
  PanelQuad *slowHLPQ;
  PanelQuad *fastforwardPQ;
  PanelQuad *fastforwardOffPQ;
  PanelQuad *fastforwardHLPQ;
  TextString *pauseText;
  float highlight_intensity;
  float highlight_timer;

public:
  void Init(PanelFile &panel, Font *font);
};

void ReplayWidget::Init(PanelFile & panel, Font *font)
{
	vcrPQ             = panel.GetPointer("replay_main2");
	vcrHLPQ           = panel.GetPointer("replay_main3");
	vcrBGPQ           = panel.GetPointer("replay_main4");
	restartPQ         = panel.GetPointer("replay_restart");
	restartOffPQ      = panel.GetPointer("replay_restart_off");
	restartHLPQ       = panel.GetPointer("replay_restart_hilite");
	pausePQ           = panel.GetPointer("replay_pause");
	pauseOffPQ        = panel.GetPointer("replay_pause_off");
	pauseHLPQ         = panel.GetPointer("replay_pause_hilite");
	playPQ            = panel.GetPointer("replay_play");
	playOffPQ         = panel.GetPointer("replay_play_off");
	playHLPQ          = panel.GetPointer("replay_play_hilite");
	slowPQ            = panel.GetPointer("replay_slowforward");
	slowOffPQ         = panel.GetPointer("replay_slowforward_off");
	slowHLPQ          = panel.GetPointer("replay_slowforward_hilite");
	fastforwardPQ     = panel.GetPointer("replay_fastforward");
	fastforwardOffPQ  = panel.GetPointer("replay_fastforward_off");
	fastforwardHLPQ   = panel.GetPointer("replay_fastforward_hilite");

  pauseText->setFont(font);

  highlight_intensity = 0.0f;
  highlight_timer     = 0.0f;
}
